import type {AudioDefinition, AudioDirection, AudioManifest} from '@roomriddle/shared-types';

/**
 * Sounds every mystery shares: menu/puzzle/ending music, discovery and unlock
 * stings, and the remote's UI sounds. PLACEHOLDERS generated by
 * apps/tv/scripts/gen-placeholder-audio.py; final audio replaces the files.
 */
const GEN = 'Generated placeholder (RoomRiddle, gen-placeholder-audio.py); replace before release.';

const s = (id: string, channel: AudioDefinition['channel'], description: string, extra: Partial<AudioDefinition> = {}): AudioDefinition => {
  const [, kind, name] = id.split('.');
  return {
    id,
    channel,
    loop: channel === 'music' || channel === 'ambient',
    status: 'placeholder',
    source: `${kind}-${name}.mp3`,
    description,
    license: GEN,
    ...extra,
  };
};

export const coreAudioManifest: AudioManifest = {
  idPrefix: 'core.',
  basePath: 'audio/core',
  sounds: [
    s('core.music.menu', 'music', 'Main menu and library: slow minor pad with a distant bell.', {volume: 0.7}),
    s('core.music.puzzle', 'music', 'Working a puzzle: brighter pad with a ticking arpeggio.', {volume: 0.6}),
    s('core.music.ending', 'music', 'The ending: resolved pad, bells.', {volume: 0.7}),
    s('core.sfx.discovery', 'sfx', 'A clue is found: rising four-note bell.', {volume: 0.8}),
    s('core.sfx.unlock', 'sfx', 'A puzzle unlocks: three-note bell.', {volume: 0.8}),
    s('core.ui.focus', 'sfx', 'Focus moved (very quiet tick).', {volume: 0.35}),
    s('core.ui.select', 'sfx', 'OK pressed.', {volume: 0.6}),
    s('core.ui.back', 'sfx', 'Back pressed.', {volume: 0.6}),
    s('core.ui.success', 'sfx', 'Right answer.', {volume: 0.8}),
    s('core.ui.failure', 'sfx', 'Wrong answer (soft, never harsh).', {volume: 0.7}),
    s('core.ui.hint', 'sfx', 'A hint is revealed.', {volume: 0.6}),
    s('core.ui.joined', 'sfx', 'A phone joined the room.', {volume: 0.7}),
    s('core.ui.left', 'sfx', 'A phone left the room.', {volume: 0.6}),
    s('core.ui.error', 'sfx', 'Something went wrong (connection, refusal).', {volume: 0.6}),
    s('core.ui.transition', 'sfx', 'Screen change whoosh.', {volume: 0.4}),
  ],
};

/** Music every mystery gets unless it chooses its own. */
export const coreMusic: AudioDirection['music'] = {
  menu: 'core.music.menu',
  selection: 'core.music.menu',
  puzzle: 'core.music.puzzle',
  ending: 'core.music.ending',
};

